import {enhanceWorkspace} from './workspace.mjs?v=ray1';
import {seed,optimise} from './engine.mjs';
const $=s=>document.querySelector(s), money=n=>'₹'+Math.round(n).toLocaleString('en-IN'), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=structuredClone(seed), storageWarning=false;
try{const saved=JSON.parse(localStorage.getItem('manta-v1'));if(saved&&Array.isArray(saved.devices)&&saved.donor&&Array.isArray(saved.evidence))state=saved;}catch{storageWarning=true;}
let page='overview', undoState=null, toastTimer;const routes=[['overview','◫','Overview'],['inventory','▱','Inventory'],['evidence','◎','Market evidence'],['planner','⌘','Recovery planner'],['review','☷','Plan review']];
function save(keepUndo=false){if(!keepUndo)undoState=null;state.approved=null;persist();}
function persist(){try{localStorage.setItem('manta-v1',JSON.stringify(state));}catch{toast('Browser storage unavailable. Export your plan before leaving.');}}
function toast(msg,undo=false){
 clearTimeout(toastTimer);
 const t=$('#toast');t.replaceChildren(document.createTextNode(msg));
 if(undo){const button=document.createElement('button');button.type='button';button.className='toast-undo';button.textContent='Undo';button.onclick=()=>{if(undoState){state=undoState;undoState=null;persist();render();toast('Restored.');}};t.append(button);}
 t.style.display='flex';toastTimer=setTimeout(()=>t.style.display='none',undo?15000:5000);
}
function title(eyebrow,name,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1><p>${sub}</p></div>${action}</div>`;}
function btn(text,action,primary=false){return `<button class="button ${primary?'primary':''}" data-action="${action}">${text}</button>`;}
function stats(plan){return `<div class="stats">${[[state.devices.length,'Devices in batch','Ready for assessment','▱'],[money(plan.net),'Estimated net recovery','After repair & selling allowances','↗'],[money(plan.uplift),'Additional recovery','Compared with selling all as-is','+'],[money(plan.spend),'Repair spend',`${plan.hours} of ${state.hours} technician hours`,'◷']].map(([value,label,hint,icon])=>`<div class="stat"><div class="stat-label">${label}<span>${icon}</span></div><strong>${value}</strong><small>${hint}</small></div>`).join('')}</div>`;}
function badge(action){return `<span class="badge ${action==='Sell as-is'?'neutral':action==='Donate part'?'amber':''}">${esc(action)}</span>`;}
function deviceTable(plan,full=false){return `<div class="table-wrap"><table><thead><tr><th>Device</th>${full?'<th>Finding</th>':''}<th>Suggested route</th><th>Net recovery</th>${full?'<th></th>':''}</tr></thead><tbody>${state.devices.map(d=>{const row=plan.rows.find(r=>r.id===d.id);return `<tr><td><div class="device-title"><span class="device-icon">▱</span><div><strong>${esc(d.model)}</strong><small>${esc(d.id)} · ${esc(d.spec)}</small></div></div></td>${full?`<td>${esc(d.fault)}<small>Required: ${esc(d.part)}</small></td>`:''}<td>${badge(row.action)}</td><td>${money(row.net)}</td>${full?`<td><button class="text-link" data-edit="${esc(d.id)}">Edit ↗</button></td>`:''}</tr>`;}).join('')}</tbody></table></div>`;}
function overview(plan){return title('A second life starts here','Good work starts with a better plan.','Your recovery workspace, from first inspection to final decision.',btn('+ Add device','add',true))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">BATCH 001 / OCTOBER INTAKE</div><h2>Small repairs.<br>Bigger possibilities.</h2><p>Find the best path for every laptop. Balance your budget, reuse good parts, and recover more value.</p><a class="button primary" href="#planner">Build recovery plan <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="laptop">⌁</div><div class="art-tag a">● A new life, within reach</div><div class="art-tag b">↗ ${money(plan.uplift)} potential uplift</div></div></section>`+stats(plan)+`<div class="columns"><section class="panel"><div class="panel-head"><div><h2>Your current batch</h2><p>${state.devices.length} devices · Illustrative assessment values</p></div><a class="text-link" href="#inventory">View inventory ↗</a></div>${deviceTable(plan)}</section><div><section class="panel"><div class="panel-head"><h2>From intake to impact</h2><span class="badge">MVP workflow</span></div>${[['01','Confirm your inventory','Check model details and technician findings.'],['02','Review the evidence','Add supplier prices and resale observations.'],['03','Choose your recovery plan','Set a budget, review, then approve.']].map(([n,t,p])=>`<div class="mini-row"><span class="step">${n}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</section><section class="panel"><span class="badge">DONOR OPPORTUNITY</span><h3>One good part. Another working laptop.</h3><div class="donor-flow">${esc(state.donor.from)} <span>→</span> ${esc(state.donor.to)}</div><p>A technician-confirmed memory match can reduce parts spend. The plan includes the donor’s residual value.</p><a class="text-link" href="#planner">Review compatibility ↗</a></section></div></div>`;}
function inventory(plan){return title('Your workshop / Inventory','Every device has a next chapter.','Record the findings that turn estimates into better decisions.',btn('+ Add device','add',true))+`<div class="note">Sample batch loaded. Confirm the physical condition and edit estimated values before making workshop decisions.</div><div class="toolbar"><input id="search" type="search" aria-label="Search inventory" placeholder="Search model, device ID, or finding…"><span class="badge neutral">${state.devices.length} / 12 devices</span></div><section class="panel" id="inventory-table">${deviceTable(plan,true)}</section>`;}
function evidence(){return title('Research / Evidence library','Good decisions need good evidence.','Keep the source, date, and uncertainty next to every estimate.',btn('+ Add evidence','evidence',true))+`<div class="columns"><div class="panel"><div class="panel-head"><h2>Market observations</h2><span class="badge">${state.evidence.length} records</span></div>${state.evidence.length?state.evidence.map((e,i)=>`<article class="evidence-card"><div class="spread"><span class="badge ${e.verified?'':'amber'}">${e.verified?'Reviewed':'Needs review'} · ${esc(e.kind)}</span><button class="text-link danger" data-remove-evidence="${i}">Remove</button></div><h3>${esc(e.title)}</h3><p>${esc(e.device)} · ${money(e.price)} · Observed ${esc(e.date)}</p><p>${esc(e.notes)}</p><a class="text-link" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join(''):`<div class="empty"><div class="device-icon">◎</div><h3>Your evidence library is ready.</h3><p>Add a supplier quote or resale observation.<br>The sample inventory uses illustrative values, not live listings.</p><br>${btn('Add first observation','evidence',true)}</div>`}</div><div><section class="panel"><span class="badge amber">CONNECTION REQUIRED</span><h3>TinyFish market research</h3><p>The live research connection is not configured. This MVP supports manual evidence capture; no web-agent run has been performed.</p><hr style="border:0;border-top:1px solid #e5ebe4;margin:20px 0"><p>Planned flow: model + part → supplier and resale research → dated source records → technician review.</p></section><section class="note">Asking prices are not completed-sale prices. Review condition, shipping, warranty and availability. Evidence records do not overwrite inventory values automatically; use Inventory → Edit after review.</section></div></div>`;}
function planner(plan){return title('Decisions / Recovery planner','Make the most of what you have.','Compare the whole batch within your budget and technician capacity.',`<a class="button primary" href="#review">Review plan ↗</a>`)+`<section class="panel"><div class="panel-head"><div><h2>Your operating limits</h2><p>Updates recalculate the best feasible plan immediately.</p></div><span class="badge">Exact batch comparison</span></div><div class="controls"><div><label for="budget">Repair budget · parts + labour</label><input id="budget" type="number" min="0" max="1000000" step="100" value="${state.budget}"><div class="plan-line"><span style="width:${state.budget?Math.min(100,plan.spend/state.budget*100):0}%"></span></div><div class="spread"><span>${money(plan.spend)} allocated</span><span>${money(state.budget-plan.spend)} remaining</span></div></div><div><label for="hours">Available technician hours</label><input id="hours" type="number" min="0" max="10000" step="0.5" value="${state.hours}"><div class="plan-line"><span style="width:${state.hours?Math.min(100,plan.hours/state.hours*100):0}%"></span></div><div class="spread"><span>${plan.hours} hours allocated</span><span>${state.hours-plan.hours} hours remaining</span></div></div></div></section>`+stats(plan)+`<div class="columns"><section class="panel"><div class="panel-head"><h2>Recommended allocation</h2><span class="badge">Within limits</span></div>${deviceTable(plan)}</section><section class="panel"><h2>Verified donor match</h2><p>Configure one compatible component for this batch.</p><br><div class="form-grid"><div><label for="donor-from">Donor</label><select id="donor-from">${options(state.donor.from)}</select></div><div><label for="donor-to">Recipient</label><select id="donor-to">${options(state.donor.to)}</select></div><div><label for="residual">Donor residual value (₹)</label><input id="residual" type="number" min="0" max="1000000" value="${state.donor.residual}"></div><div><label for="donor-hours">Removal time (hours)</label><input id="donor-hours" type="number" min="0" max="100" step="0.5" value="${state.donor.hours}"></div><label class="field-wide inline-check"><input id="confirmed" type="checkbox" ${state.donor.confirmed?'checked':''}> Technician confirms part health and compatibility</label></div><div class="note">The match replaces the recipient’s full required part. Include all removal labour charges in the recipient’s labour estimate. The donor cannot also be repaired.</div></section></div>`;}
function options(selected){return state.devices.map(d=>`<option value="${esc(d.id)}" ${d.id===selected?'selected':''}>${esc(d.id)} · ${esc(d.model)}</option>`).join('');}
function review(plan){return title('Decisions / Plan review','A clear path for every device.','Review the assumptions and calculations before approving workshop work.',btn('↓ Export CSV','export'))+stats(plan)+`<section class="panel"><div class="panel-head"><div><h2>Recovery plan · Batch 001</h2><p>${state.approved?'Approved '+new Date(state.approved).toLocaleString():'Draft · waiting for your review'}</p></div><span class="badge ${state.approved?'':'amber'}">${state.approved?'Approved':'Review required'}</span></div><div class="table-wrap"><table><thead><tr><th>Device</th><th>Decision</th><th>Repair spend</th><th>Hours</th><th>Net recovery</th><th>Vs. as-is</th></tr></thead><tbody>${plan.rows.map(r=>{const d=state.devices.find(d=>d.id===r.id);return `<tr><td><strong>${esc(d.model)}</strong><small>${esc(d.id)}</small></td><td>${badge(r.action)}</td><td>${money(r.cost)}</td><td>${r.hours} h</td><td>${money(r.net)}</td><td class="${r.net-d.asIs>=0?'green':'danger'}">${money(r.net-d.asIs)}</td></tr>`;}).join('')}</tbody></table></div><div class="approval"><div><div class="eyebrow">Estimated additional recovery</div><div class="review-total">+ ${money(plan.uplift)}</div><p>${money(plan.net)} planned recovery − ${money(plan.baseline)} sell-all-as-is baseline</p></div>${btn(state.approved?'✓ Plan approved':'Approve this plan','approve',true)}</div></section><div class="columns"><section class="panel"><h2>What the numbers mean</h2><p><b>Repair:</b> resale estimate − parts − labour − selling / warranty allowance.<br><b>Sell as-is:</b> entered net proceeds.<br><b>Donate:</b> remaining donor resale value after removing the component.<br><b>Additional recovery:</b> whole-batch plan less whole-batch as-is proceeds.</p></section><section class="note">Estimates assume successful repairs and sales. They exclude acquisition cost and overhead. Confirm part condition, market evidence and actual repair risks. Approval records your decision locally; it does not place orders or instruct a technician.</section></div>`;}
function render(){page=location.hash.slice(1)||'overview';if(!routes.some(r=>r[0]===page))page='overview';const plan=optimise(state);$('nav[aria-label="Main navigation"]').innerHTML=routes.map(([id,icon,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</a>`).join('');$('#breadcrumb').textContent=routes.find(r=>r[0]===page)[2];$('#app').innerHTML=({overview,inventory,evidence,planner,review}[page])(plan);bind();enhanceWorkspace(state,plan,page,{save,persist,render,toast,modal});}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>deviceDialog(b.dataset.edit));document.querySelectorAll('[data-remove-evidence]').forEach(b=>b.onclick=()=>{undoState=structuredClone(state);state.evidence.splice(Number(b.dataset.removeEvidence),1);save(true);render();toast('Observation removed.',true);});$('#search')?.addEventListener('input',e=>document.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(e.target.value.toLowerCase())));for(const [id,key] of [['budget','budget'],['hours','hours']])$('#'+id)?.addEventListener('change',e=>{if(!e.target.checkValidity())return e.target.reportValidity();state[key]=Number(e.target.value);save();render();});for(const [id,key] of [['donor-from','from'],['donor-to','to'],['residual','residual'],['donor-hours','hours'],['confirmed','confirmed']])$('#'+id)?.addEventListener('change',e=>{if(!e.target.checkValidity())return e.target.reportValidity();state.donor[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;if(key==='from'||key==='to'){state.donor.confirmed=false;toast('Match changed. Confirm compatibility again.');}save();render();});}
function action(a){if(a==='add')deviceDialog();if(a==='evidence'){if(!state.devices.length){toast('Add a device before recording evidence.');return;}evidenceDialog();}if(a==='export')exportPlan();if(a==='approve'){if(!state.devices.length)return toast('Add a device before approving a plan.');state.approved=new Date().toISOString();persist();render();toast('Plan approved and saved on this browser.');}}
function field(key,label,value,type='text',extra=''){return `<div><label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${extra} required></div>`;}
function modal(html,onSubmit){const m=$('#modal');m.innerHTML=html;const h=m.querySelector('h2');if(h){h.id='dialog-title';m.setAttribute('aria-labelledby','dialog-title');}m.showModal();m.querySelector('[data-close]').onclick=()=>m.close();m.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.target));};}
function deviceDialog(id){if(!id&&state.devices.length>=12)return toast('This MVP supports up to 12 devices.');const d=state.devices.find(d=>d.id===id)||{model:'',spec:'',fault:'',part:'',asIs:0,resale:0,parts:0,labour:0,fees:0,hours:1};modal(`<form><h2>${id?'Edit device':'Add a device'}</h2><div class="form-grid">${field('model','Model',d.model,'text','maxlength="100"')}${field('spec','Specification',d.spec,'text','maxlength="100"')}${field('fault','Technician finding',d.fault,'text','maxlength="200"')}${field('part','Required replacement part',d.part,'text','maxlength="100"')}${[['asIs','As-is net proceeds (₹)'],['resale','Expected resale (₹)'],['parts','Parts cost (₹)'],['labour','Labour cost (₹)'],['fees','Selling / warranty allowance (₹)'],['hours','Repair time (hours)']].map(([k,l])=>field(k,l,d[k],'number',`min="0" max="1000000" step="${k==='hours'?'0.5':'1'}"`)).join('')}</div><p class="subtle">Enter estimates based on technician findings and reviewed evidence.</p><div class="dialog-actions">${id?'<button type="button" class="button danger" id="delete-device">Remove device</button>':''}<button type="button" class="button" data-close>Cancel</button><button class="button primary">Save device</button></div></form>`,data=>{const next=Object.fromEntries(data);for(const k of ['asIs','resale','parts','labour','fees','hours'])next[k]=Number(next[k]);next.id=id||'M-'+String(Math.max(0,...state.devices.map(d=>Number(d.id.slice(2))||0))+1).padStart(3,'0');if(id)state.devices[state.devices.findIndex(d=>d.id===id)]=next;else state.devices.push(next);if(id===state.donor.from||id===state.donor.to)state.donor.confirmed=false;save();$('#modal').close();render();toast('Device saved. Recovery plan updated.');});$('#delete-device')?.addEventListener('click',()=>{undoState=structuredClone(state);state.devices=state.devices.filter(d=>d.id!==id);if(id===state.donor.from||id===state.donor.to)state.donor.confirmed=false;save(true);$('#modal').close();render();toast('Device removed.',true);});}
function evidenceDialog(){modal(`<form><h2>Add market evidence</h2><div class="form-grid">${field('title','Observation title','','text','maxlength="160"')}<div><label for="kind">Evidence type</label><select name="kind" id="kind"><option>Supplier quote</option><option>Resale asking price</option><option>Completed sale</option></select></div><div><label for="device">Device</label><select name="device" id="device">${options('')}</select></div>${field('price','Observed price (₹)',0,'number','min="0" max="1000000"')}${field('url','Source URL','','url')}${field('date','Observed date',new Date().toLocaleDateString('en-CA'),'date','max="'+new Date().toLocaleDateString('en-CA')+'"')}<div class="field-wide"><label for="notes">Condition, shipping, uncertainty</label><textarea name="notes" id="notes" maxlength="1000" rows="3"></textarea></div><label class="field-wide inline-check"><input type="checkbox" name="verified"> I reviewed the source and its relevance</label></div><div class="dialog-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary">Save evidence</button></div></form>`,data=>{const e=Object.fromEntries(data);if(!/^https?:\/\//i.test(e.url))return toast('Use an http or https source URL.');e.price=Number(e.price);e.verified=data.has('verified');state.evidence.push(e);save();$('#modal').close();render();toast('Evidence saved. Update inventory values after review.');});}
function exportPlan(){const p=optimise(state),cell=v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';const rows=[['MANTA recovery plan',state.approved?'Approved '+state.approved:'Draft'],['Estimates exclude acquisition and overhead'],['ID','Model','Decision','Repair spend INR','Hours','Net recovery INR'],...p.rows.map(r=>[r.id,state.devices.find(d=>d.id===r.id).model,r.action,r.cost,r.hours,r.net]),[],['Total recovery',p.net],['As-is baseline',p.baseline],['Additional recovery',p.uplift],['Budget',state.budget],['Hours available',state.hours]];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='manta-recovery-plan.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Plan exported.');}
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();document.querySelector('#app').focus();});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});render();if(storageWarning)toast('Saved data could not be read. Sample batch loaded.');
